WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_essay_topic'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '立意与破题', 'kp-sl-essay-topic', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "大作文：立意与破题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "偏题必死。立意必须紧扣最后一道题的“题眼”，并结合全篇材料的宏观主旨。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、找准总论点"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“题眼”往往是作文题目中给出的一句话。这句话里的核心名词或动宾搭配，就是你的总论点。"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "如果题干说：“结合对‘慢即是快’的理解写一篇文章”。你的总论点必须是论述为什么慢能带来快，如何在发展中把握慢的智慧。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "结合整篇材料：如果全篇材料都在讲“城市建设”、“工匠精神”。你的立意就必须是：【在城市建设中秉持工匠精神，懂得慢即是快的哲理】。绝不能脱离具体材料空谈人生哲理！"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "自作聪明写反向：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "申论不是杂文，绝不能为了显得自己“独特”而写与材料主旋律相反的论点。政府的主旋律是维稳和正能量，你的立意必须在材料给定的框框里跳舞。"}]}]}]}$$ AS jsonb), NULL, '立意与破题的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "大作文", "立意破题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_essay_topic", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
